#!/usr/bin/env python3
"""Build dependency-free, bilingual GitHub Pages HTML. Run: python3 scripts/build.py."""
import json
from pathlib import Path
from html import escape as esc
from urllib.parse import quote

ROOT = Path(__file__).resolve().parents[1]
SERVICES = json.loads((ROOT/'data/services.json').read_text())['services']
BASE = 'https://gkkm8bm7rn-eng.github.io/portfolio/'

def tr(ru,en): return ru if LANG=='ru' else en
def e(s): return esc(str(s), quote=True)
def contact_url():
    return 'https://wa.me/79054076340?text='+quote(tr('Здравствуйте! Хочу обсудить проект с дизайн-студией.','Hello! I would like to discuss a project with Design Studio.'))
def email_url(): return 'mailto:sherxanova@gmail.com?subject='+quote(tr('Проект для дизайн-студии','Project inquiry — Design Studio'))
def link(href,label,cls='',external=False):
    return f'<a href="{e(href)}"'+(f' class="{cls}"' if cls else '')+(' target="_blank" rel="noopener noreferrer"' if external else '')+f'>{label}</a>'
def actions():
    return '<div class="actions">'+link(contact_url(),tr('Написать в WhatsApp','Message on WhatsApp'),'button',True)+link(email_url(),tr('Написать на почту','Send an email'),'button secondary')+'</div>'
def img(name,alt,cls='',eager=False):
    p=ROOT/'assets/studio'/name
    # Dimensions stored by asset preparation; no runtime dependency on image parsing.
    sizes=json.loads((ROOT/'data/image-sizes.json').read_text())
    w,h=sizes.get(name,[1440,960])
    return f'<img src="{PREFIX}assets/studio/{name}" alt="{e(alt)}" width="{w}" height="{h}" class="{cls}" '+('fetchpriority="high"' if eager else 'loading="lazy"')+' decoding="async">'
def figure(name,alt,caption='',cls='',eager=False):
    return f'<figure class="{cls}">{img(name,alt,eager=eager)}'+(f'<figcaption>{caption}</figcaption>' if caption else '')+'</figure>'
def section(id,title,text,media='',reverse=False):
    return f'<section class="case-section wrap {"reverse" if reverse else ""}" id="{id}"><div class="case-section-copy"><h2>{title}</h2>{text}</div><div class="case-section-media">{media}</div></section>'
def p(text):return '<p>'+text+'</p>'
def intro(kicker,title,lead,kind='page-intro'):
    return f'<section class="{kind} wrap"><p class="hero-kicker">{kicker}</p><h1>{title}</h1><p class="lede">{lead}</p></section>'
def facts(items):
    return '<dl class="case-facts wrap">'+''.join(f'<div><dt>{a}</dt><dd>{b}</dd></div>' for a,b in items)+'</dl>'
def result(title,text):return f'<section class="case-result wrap"><h2>{title}</h2><p>{text}</p></section>'
def contact(title=None):
    return '<section class="contact-section wrap" id="contact"><p class="hero-kicker">'+tr('Контакты','Contact')+'</p><h2>'+ (title or tr('Обсудим вашу задачу?','Let’s discuss your project.'))+'</h2><p>'+tr('Расскажите о продукте, сроках и нужном результате. Начнём с задачи и определим подходящий объём работы.','Tell us about your product, timeline, and the result you need. We will start with the brief and agree on the right scope.')+'</p>'+actions()+'<div class="contact-details">'+link('tel:+79054076340','+7 905 407 63 40')+link(email_url(),'sherxanova@gmail.com')+'</div></section>'

PROJECTS=[
 ('otutto.html','ОТУТТО','OTUTTO','otutto-final.webp', 'Мебель · Визуальная система · Сайт','Furniture · Visual system · Website', 'От образа изделия до сайта мебельного бренда.','From a product image to a furniture brand website.'),
 ('forma-home.html','TETOpt','TETOpt','tetopt-catalog.webp','Товарные данные · Цифровой каталог','Product data · Digital catalog','Таблица ассортимента становится инструментом выбора и заказа.','An assortment spreadsheet becomes a tool for selection and inquiry.'),
 ('materials.html','Форма и материал','Form & material','otutto-source.webp','Предметный дизайн · Текстиль','Product design · Textiles','Работа с формой, обивкой и деталями реального изделия.','Working with the form, upholstery, and details of a real product.'),
 ('silence.html','Тишина','Silence','silence-01-hero.webp','Авторский проект · Визуальная серия','Independent project · Visual series','Четыре ракурса одного образа из «Последнего каталога».','Four views of one idea from The Last Catalog.')]
def card(item,i):
    url,ru,en,photo,catru,caten,desc,descen=item
    return f'<article class="project-card {"large" if i%2==0 else "small"}"><a class="project-image" href="{url}" tabindex="-1" aria-hidden="true">'+img(photo,tr(ru,en))+f'</a><p class="project-meta">{tr(catru,caten)}</p><h3>{link(url,tr(ru,en))}</h3><p>{tr(desc,descen)}</p>'+link(url,tr('Смотреть проект','View project'),'project-link')+'</article>'
def projects_grid(items=PROJECTS):return '<div class="project-grid">'+''.join(card(it,i) for i,it in enumerate(items))+'</div>'
def home():
    hero='<section class="art-cover" aria-labelledby="cover-title"><div class="cover-intro"><h1 id="cover-title">'+tr('<span>Предметный дизайн.</span> <span>Визуальные системы.</span> <span>Цифровые продукты.</span>','<span>Product design.</span> <span>Visual systems.</span> <span>Digital products.</span>')+'</h1></div><div class="art-stage">'
    hero+='<a class="cover-work cover-work-main" href="silence.html#author-place"><figure>'+img('girl-on-cube.webp',tr('Девушка на каменном кубе рядом с зеркалом — художественный образ «Последнего каталога».','A woman on a stone cube beside a mirror — an artwork from The Last Catalog.'),eager=True)+'<figcaption><span>'+tr('Место автора','The author’s place')+'</span><small>'+tr('«Последний каталог»','The Last Catalog')+'</small></figcaption></figure></a>'
    hero+='<a class="cover-work cover-work-silence" href="silence.html"><figure><div class="silence-visual">'+img('silence-cover.webp',tr('«Тишина» — прозрачный скульптурный объект на светлом постаменте.','Silence — a transparent sculptural object on a pale pedestal.'),eager=True)+'</div><figcaption><span>'+tr('Тишина','Silence')+'</span><small>'+tr('Визуальная серия','Visual series')+'</small></figcaption></figure></a></div>'
    hero+='<div class="cover-footer"><a class="cover-scroll" href="#projects"><span class="scroll-line" aria-hidden="true"></span>'+tr('Листайте к проектам','Scroll to projects')+'</a>'+link(contact_url(),tr('Обсудить проект','Discuss a project'),'cover-contact',True)+'</div></section>'
    featured='<section class="wrap projects-section" id="projects"><div class="section-head"><h2>'+tr('Избранные<br>проекты','Selected<br>projects')+'</h2>'+link('projects.html',tr('Все проекты','All projects'),'text-link')+'</div>'+projects_grid(PROJECTS[:2])+'</section>'
    silence='<section class="silence-feature"><div class="wrap silence-layout">'+figure('silence-01-hero.webp',tr('«Тишина»: прозрачная оболочка на каменном постаменте','Silence: a transparent membrane on a stone pedestal'))+'<div class="silence-copy"><p class="hero-kicker">'+tr('«Последний каталог» · Авторская серия','The Last Catalog · Independent series')+'</p><h2>'+tr('Увидеть<br>тишину.','Making silence<br>visible.')+'</h2><p>'+tr('Как показать то, у чего нет формы? Тонкая оболочка, мягкий свет и четыре самостоятельных кадра — визуальный язык одного объекта.','How do you show something with no form? A fine membrane, soft light, and four individual images establish a visual language for one object.')+'</p>'+link('silence.html',tr('Смотреть серию','Explore the series'),'text-link')+'</div></div></section>'
    material='<section class="wrap studio-note"><div><p class="hero-kicker">'+tr('Предметная практика','Product design practice')+'</p><h2>'+tr('Сначала —<br>сам предмет.','The object<br>comes first.')+'</h2></div><div><p>'+tr('Форма, фактура, сочетание тканей и бюджет изделия определяют решение. Визуализация помогает его проверить и показать, но не заменяет работу с реальными материалами.','Form, texture, fabric combinations, and the product budget guide each decision. Visualization helps review and present it, while real materials remain the basis of the work.')+'</p>'+link('materials.html',tr('О работе с материалами','Material selection in practice'),'text-link')+'</div></section>'
    srv='<section class="wrap services-section" id="services"><div class="section-head"><h2>'+tr('Чем можем<br>помочь','What we<br>can do')+'</h2>'+link('price.html',tr('Услуги и цены','Services & pricing'),'text-link')+'</div><div class="services-preview">'
    for t,d in [(tr('Предмет и материал','Product & material'),tr('Мебель, ткани, фактуры и цветовые сочетания с учётом задачи и стоимости.','Furniture, fabrics, textures, and color combinations informed by the brief and budget.')),(tr('Визуальная подача','Visual presentation'),tr('Образы изделий, коммерческие предложения и PDF-каталоги.','Product visuals, commercial proposals, and PDF catalogs.')),(tr('Цифровой каталог','Digital catalogs'),tr('Товарные данные, сайты-каталоги и понятный путь к обращению.','Product data, catalog websites, and a clear path to an inquiry.'))]:
        srv+=f'<article><h3>{t}</h3><p>{d}</p></article>'
    return hero+'<div class="portfolio-body">'+featured+silence+material+srv+'</div></section>'+contact()+'</div>'

def price():
    out=intro(tr('Услуги и стоимость','Services & pricing'),tr('Понятный объём.<br><em>Открытые цены.</em>','A clear scope.<br><em>Open pricing.</em>'),tr('От отдельной визуальной серии до сайта мебельного бренда. Выберите отправную точку — точную стоимость определим по материалам и объёму задачи.','From a visual series to a furniture brand website. Choose a starting point; the final quote depends on the source material and scope.'))
    out+='<div class="price-intro-note wrap"><p>'+tr('Все суммы — в рублях. Это предварительные стартовые цены, а не фиксированная стоимость любого проекта. Ниже указан базовый объём; дополнительные задачи согласуются отдельно.','All prices are in Russian rubles. These are preliminary starting prices, rather than fixed fees for any project. The basic scope is listed below; additions are agreed separately.')+'</p></div><section class="price-list wrap" aria-label="'+tr('Услуги и базовый объём','Services and basic scope')+'">'
    for s in SERVICES:
        t=s[LANG]; price=tr('индивидуально','Quoted individually') if s['priceRub'] is None else tr('от ','from ')+f"{s['priceRub']:,}".replace(',','\u202f')+' ₽'
        out+=f'<article class="price-item" id="{s["id"]}"><div class="price-heading"><h2>{e(t["title"])}</h2><p class="price-value">{price}</p></div><div class="price-content"><p>{e(t["description"])}</p><div class="scope-grid"><div><h3>'+tr('Базовый объём','Basic scope')+f'</h3><p>{e(t["scope"])}</p></div><div><h3>'+tr('Что влияет на стоимость','What affects the cost')+f'</h3><p>{e(t["costFactors"])}</p></div></div><div class="case-reference">'+link(s['caseHref'],e(t['caseLabel']),'text-link')+(p(e(t['exampleNote'])) if t['exampleNote'] else '')+'</div></div></article>'
    out+='</section><section class="price-cta wrap"><h2>'+tr('Не нашли нужную услугу?','Looking for another service?')+'</h2><p>'+tr('Опишите задачу — предложим подходящий формат работы и рассчитаем стоимость.','Describe your task — we will suggest a suitable way to work together and prepare a quote.')+'</p>'+actions()+'</section>'
    return out

def otutto():
    out=intro(tr('ОТУТТО · Мебель и цифровая подача','OTUTTO · Furniture & digital presentation'),tr('Один бренд.<br><em>Несколько точек контакта.</em>','One brand.<br><em>Connected touchpoints.</em>'),tr('Визуализация изделия, коммерческий документ и демонстрационный сайт. Части одного проекта, в котором мебель должна быть понятна до личного знакомства.','Product visualization, a commercial document, and a demonstration website. Parts of one project that makes furniture understandable before seeing it in person.'),'case-hero')
    out+='<div class="case-cover wrap">'+figure('otutto-final.webp',tr('Оранжевый диван ОТУТТО: визуализация выбранной формы и обивки','OTUTTO orange sofa: visualization of the selected form and upholstery'),tr('Визуализация изделия. Не фотография готового дивана.','Product visualization, rather than a photograph of the finished sofa.'),eager=True)+'</div>'
    out+=facts([(tr('Задача','Brief'),tr('Связать изделие, материалы и визуальную подачу.','Connect the product, its materials, and visual presentation.')),(tr('Вклад','Contribution'),tr('Работа с формой и обивкой, визуализация, коммерческая подача и сайт.','Form and upholstery decisions, visualization, commercial presentation, and website.')),(tr('Условия','Context'),tr('Реальные исходные фотографии. Сайт — демонстрационный проект.','Real source photographs. The website is a demonstration project.'))])
    out+=section('approach',tr('Начать с реального изделия','Start with a real product'),p(tr('Фото дивана из салона и разметка деталей задают форму, пропорции и зоны изменения. Визуализация собирает их в общий образ для обсуждения.','A showroom photograph and marked-up details establish the form, proportions, and areas to change. Visualization brings them together into a view that can be discussed.'))+p(tr('Предметные решения и подбор материала — самостоятельная работа автора. ИИ используется как вспомогательный инструмент визуализации.','Product decisions and material selection are the author’s own work. AI supports the visualization process.'))+link('materials.html',tr('Подробнее о форме и материалах','More about form and materials'),'text-link'),'<div class="image-pair">'+figure('otutto-source.webp',tr('Исходное фото дивана в салоне','Original showroom photograph of the sofa'),tr('Исходное изделие','Source product'))+figure('otutto-markup.webp',tr('Разметка формы и деталей дивана','Marked-up sofa form and details'),tr('Разметка деталей','Detail markup'))+'</div>')
    out+=section('website',tr('Сайт как продолжение коллекции','A website built around the collection'),p(tr('Проверенная структура включает 22 содержательные страницы: главную, коллекцию, страницы моделей, информацию о производстве и журнал. В коллекции есть поиск по моделям; фотографии можно открыть крупнее.','The verified structure contains 22 content pages: home, collection, model pages, production information, and a journal. The collection supports model search, and photographs can be opened at a larger size.'))+p(tr('Сдержанная типографика и крупные изображения оставляют мебель в центре внимания. На телефоне работает отдельное меню. Сайт демонстрирует структуру и интерфейс; подключённой системы заявок, корзины и оплаты в нём нет.','Restrained typography and large images keep the furniture in focus. A dedicated menu supports mobile navigation. The site demonstrates structure and interface; it has no connected inquiry system, cart, or payment flow.'))+link('https://gkkm8bm7rn-eng.github.io/Otutto/',tr('Открыть демонстрационный сайт','Open the demonstration website'),'text-link',True),figure('otutto-home.webp',tr('Настоящий скриншот главной страницы сайта ОТУТТО','Actual screenshot of the OTUTTO website homepage'),tr('Скриншот интерфейса из репозитория Otutto.','Interface captured from the Otutto repository.'),'media-frame'))
    out+='<div class="wrap">'+figure('otutto-collection.webp',tr('Настоящий интерфейс коллекции ОТУТТО с поиском моделей','Actual OTUTTO collection interface with model search'),tr('Коллекция: настоящие модели и поиск по ассортименту.','Collection: real models and assortment search.'),'media-frame')+'</div>'
    out+=section('commercial',tr('Изделие и условия — в одном документе','Product and terms in one document'),p(tr('Коммерческое предложение для модели Palermo объединяет образ, размеры, конфигурацию, материал и ценовые условия. Заказчику не нужно собирать информацию из разных сообщений.','The Palermo commercial proposal brings together the product image, dimensions, configuration, material, and pricing terms. The customer can review the information in one place.'))+p(tr('Показан реальный одностраничный материал из портфолио. Это пример коммерческой вёрстки, а не подтверждение готового многостраничного PDF-каталога. Цены внутри изображения относятся к исходному документу.','This is an existing single-page portfolio document. It demonstrates commercial layout, rather than a completed multi-page PDF catalog. Prices in the image belong to the source document.')),figure('palermo-offer.webp',tr('Коммерческое предложение ОТУТТО для дивана Palermo','OTUTTO commercial proposal for the Palermo sofa'),tr('Исходное коммерческое предложение','Original commercial proposal'),'image-contain'),True)
    out+=section('production',tr('Показать материал и производство','Show material and making'),p(tr('Фотографии работы с кожей и готового интерьера дают предметный контекст коллекции. Для этого этапа использованы документальные кадры из публичных материалов Otutto.','Photographs of leather work and the completed interior give the collection a physical context. This stage uses documentary images from the public Otutto materials.')),'<div class="image-pair">'+figure('leather-craft.webp',tr('Работа с кожей: исходное фото производства ОТУТТО','Leather work: original OTUTTO production photograph'))+figure('leather-interior.webp',tr('Кожаный диван ОТУТТО в интерьере','OTUTTO leather sofa in an interior'))+'</div>')
    return out+result(tr('Результат, который можно рассмотреть','A result you can inspect'),tr('Сформирована связанная подача мебели: от исходного изделия и визуализации до коммерческого материала и работающего демонстрационного сайта. Данные о продажах и влиянии на конверсию не представлены.','A connected presentation of the furniture: from the source product and visualization to a commercial document and a working demonstration website. Sales and conversion results are not available.'))+related('otutto.html')+contact()

def tetopt():
    out=intro(tr('TETOpt · Данные и сайт-каталог','TETOpt · Data & catalog website'),tr('Из товарной таблицы —<br><em>в рабочий каталог.</em>','From a spreadsheet<br><em>to a working catalog.</em>'),tr('Без отдельного бюджета на разработку: структура товарных данных, поиск, фильтры и подготовка заказа в одном интерфейсе.','Built without a dedicated development budget: structured product data, search, filters, and inquiry preparation in one interface.'),'case-hero')
    out+='<div class="case-cover wrap">'+figure('tetopt-catalog.webp',tr('Настоящий интерфейс каталога TETOpt с товарными карточками','Actual TETOpt catalog interface with product cards'),tr('В текущем интерфейсе проекта используется название FORMA HOME. Название кейса в портфолио — TETOpt.','The current project interface uses the name FORMA HOME. The portfolio case is titled TETOpt.'),'media-frame',True)+'</div>'
    out+=facts([(tr('Задача','Brief'),tr('Сделать ассортимент доступным для поиска и выбора.','Make an assortment searchable and easy to choose from.')),(tr('Вклад','Contribution'),tr('Структура данных, логика каталога и адаптивный интерфейс.','Data structure, catalog logic, and responsive interface.')),(tr('Условия','Context'),tr('Статический сайт. Заказ оформляется как обращение к менеджеру.','Static website. Orders are prepared as inquiries to a manager.'))])
    out+=section('data',tr('Сначала — порядок в данных','Start by organizing the data'),p(tr('Товарная база становится основой интерфейса: категории, артикулы, характеристики, изображения и варианты изделия должны оставаться связаны. У каждого варианта сохраняются собственные данные, чтобы каталог не обещал несуществующие комбинации.','Product data forms the interface: categories, article numbers, specifications, images, and variants need to stay connected. Each variant retains its own data, so the catalog does not promise combinations that do not exist.'))+p(tr('Такой подход помогает использовать одну структуру для списка, карточки товара и обращения по выбранным позициям.','This allows one structure to support the product list, detail view, and inquiry for selected items.')),figure('tetopt-product.webp',tr('Карточка реального товара в каталоге TETOpt','Real product detail view in the TETOpt catalog'),tr('Карточка товара: изображения, варианты и характеристики.','Product detail: images, variants, and specifications.'),'media-frame'))
    out+=section('interface',tr('Найти, сравнить, сохранить','Find, compare, save'),p(tr('В действующей реализации проверены поиск по названию и артикулу, категории и подкатегории, фильтр цены, сортировка и страницы результатов. Подробная карточка помогает рассмотреть товар до обращения.','The current implementation includes search by name and article number, categories and subcategories, price filtering, sorting, and paginated results. A detailed view helps users inspect the product before making an inquiry.'))+p(tr('Избранное и корзина сохраняются в браузере. В мобильной версии фильтры открываются отдельно от списка, чтобы оставить место для товаров.','Favorites and the cart persist in the browser. On mobile, filters open separately from the list to keep products in focus.'))+link('https://gkkm8bm7rn-eng.github.io/tetopt/',tr('Открыть настоящий каталог','Open the actual catalog'),'text-link',True),figure('tetopt-mobile.webp',tr('Мобильный интерфейс TETOpt на телефоне','TETOpt mobile catalog interface'),tr('Реальный мобильный интерфейс','Actual mobile interface'),'image-contain'),True)
    out+=section('inquiry',tr('Выбор становится обращением','Turn a selection into an inquiry'),p(tr('Корзина собирает выбранные товары и количества в текст заказа для менеджера. Пользователь может перейти к WhatsApp, Telegram или почте; отправка остаётся под его контролем.','The cart turns selected products and quantities into an order text for a manager. Users can continue in WhatsApp, Telegram, or email and choose when to send.'))+p(tr('Это подготовка обращения, а не серверное оформление заказа или оплата. В кейсе не заявляются продажи или рост конверсии.','This prepares an inquiry; it is not server-side checkout or payment processing. The case makes no sales or conversion claims.')),figure('tetopt-cart.webp',tr('Настоящая корзина TETOpt с подготовкой обращения','Actual TETOpt cart with inquiry preparation'),tr('Корзина и следующий шаг к менеджеру','Cart and next step to contact a manager'),'media-frame'))
    return out+result(tr('Каталог стал инструментом','A catalog that supports a task'),tr('Ассортимент можно искать, сужать по параметрам, сохранять и собирать в обращение. Результат — работающий пользовательский сценарий, доступный для проверки в публичном проекте.','Users can search the assortment, narrow it down, save items, and collect them into an inquiry. The result is a working user flow that can be reviewed in the public project.'))+related('forma-home.html')+contact()

def materials():
    out=intro(tr('Предметный дизайн · Мебель и текстиль','Product design · Furniture & textiles'),tr('Форма начинается<br><em>с материала.</em>','Form begins<br><em>with material.</em>'),tr('На примере дивана ОТУТТО: работа с пропорциями, деталями обивки, фактурой и цветом до подготовки финального образа.','An OTUTTO sofa study: working with proportions, upholstery details, texture, and color before preparing the final visual.'),'case-hero')
    out+='<div class="case-cover wrap">'+figure('otutto-source.webp',tr('Исходное реальное фото дивана ОТУТТО в серой обивке','Original photograph of an OTUTTO sofa in gray upholstery'),tr('Реальный исходник: форма, швы и пропорции изделия.','Real source: the product’s form, seams, and proportions.'),eager=True)+'</div>'
    out+=facts([(tr('Задача','Brief'),tr('Согласовать характер изделия через форму и обивку.','Define the product’s character through form and upholstery.')),(tr('Основа','Basis'),tr('Реальное изделие и работа с материалами.','A real product and material selection.')),(tr('Вклад','Contribution'),tr('Предметные решения, сочетания фактур и цветов; контроль визуализации.','Product decisions, texture and color combinations, and visualization review.'))])
    out+=section('selection',tr('Не только цвет обивки','More than upholstery color'),p(tr('При подборе реальных тканей важны масштаб фактуры, сочетание поверхностей и соответствие бюджету. Материал должен работать с формой, а не просто хорошо выглядеть на отдельном образце.','Selecting real fabrics involves texture scale, surface combinations, and budget. A material needs to work with the form, beyond looking good on a single sample.'))+p(tr('Стоимость материала и доступность образцов уточняются для конкретного заказа.','Material cost and sample availability are checked for each commission.')),figure('otutto-markup.webp',tr('Разметка деталей и зон обивки дивана','Markup of sofa details and upholstery areas'),tr('Разметка помогает обсуждать конкретные детали.','Markup makes individual details easier to discuss.')))
    out+=section('visualization',tr('Образ для проверки решения','An image to review the decision'),p(tr('Оранжевая фактурная обивка и тёмный фон позволяют оценить характер изделия в выбранном направлении. Визуализация показывает идею до производства; она не заменяет проверки ткани вживую.','Textured orange upholstery and a dark background show the character of the proposed direction. Visualization presents an idea before production; the fabric still needs to be reviewed in person.'))+p(tr('ИИ помогает подготовить изображение. Решения по форме, ткани и сочетаниям остаются предметной работой автора. Финальный производственный результат этим изображением не подтверждается.','AI helps prepare the image. Form, fabric, and combination decisions remain the author’s product design work. This image does not establish a finished manufacturing result.')),figure('otutto-final.webp',tr('Визуализация дивана с оранжевой фактурной обивкой','Sofa visualization with textured orange upholstery'),tr('Визуализация, не фотография готового изделия.','Visualization, rather than a photograph of a finished product.')),True)
    return out+result(tr('Отдельная экспертиза внутри проекта','A distinct discipline within the project'),tr('Подбор материалов определяет сам предмет. Каталог и сайт помогают донести это решение до заказчика. В ОТУТТО эти этапы показаны как части одного проекта.','Material selection defines the object itself. The catalog and website help communicate that decision to a customer. In OTUTTO, these stages are presented as parts of one project.'))+related('materials.html')+contact()

def silence():
    out=intro(tr('«Последний каталог» · Авторский цифровой проект','The Last Catalog · Independent digital project'),tr('Тишина.<br><em>Форма невидимого.</em>','Silence.<br><em>A form for the invisible.</em>'),tr('Визуальная серия о состоянии без уведомлений и фонового шума. Четыре самостоятельных изображения одного концептуального объекта.','A visual series about a state without notifications and background noise. Four individual images of one conceptual object.'),'case-hero')
    out+='<div class="case-cover wrap">'+figure('silence-01-hero.webp',tr('Канонический образ «Тишины»: прозрачная оболочка на постаменте','The canonical Silence image: a transparent membrane on a pedestal'),tr('Оригинал из the-last-catalog · «Тишина», главный образ.','Original from the-last-catalog · Silence, main image.'),'image-contain',True)+'</div>'
    out+=facts([(tr('Задача','Brief'),tr('Сделать нематериальное состояние видимым.','Make an intangible state visible.')),(tr('Условия','Context'),tr('Авторский концепт, не серийный товар и не коммерческая съёмка.','An independent concept, rather than a manufactured product or commercial photoshoot.')),(tr('Средства','Medium'),tr('Художественная концепция и визуализация с помощью ИИ.','Art direction and AI-assisted visualization.'))])
    out+=section('idea',tr('Оболочка удерживает пустоту','A membrane holding emptiness'),p(tr('Тишина не имеет собственной формы. Тонкая почти бесцветная плёнка делает видимым пространство, которое её удерживает. Мягкий боковой свет и каменный постамент связывают образ с языком предметного каталога.','Silence has no form of its own. A fine, almost colorless membrane makes the space holding it visible. Soft side light and a stone pedestal connect the image to the language of a product catalog.'))+p(tr('Визуальный принцип зафиксирован в исходном проекте: это лёгкая оболочка, а не стеклянная скульптура.','The original project defines the visual principle: a light membrane, rather than a glass sculpture.')),figure('silence-02-material.webp',tr('Макро плёнки и точки натяжения объекта «Тишина»','Macro view of the Silence membrane and tension point'),tr('Деталь материала','Material detail')))
    out+='<section class="wrap"><div class="section-head"><h2>'+tr('Одна серия.<br>Разные задачи кадра.','One series.<br>Different roles for each view.')+'</h2></div><div class="image-pair">'+figure('silence-03-catalog.webp',tr('Альтернативный каталожный ракурс «Тишины»','Alternative catalog view of Silence'),tr('Каталожный ракурс: объект и его пропорции.','Catalog view: the object and its proportions.'))+figure('silence-04-scale.webp',tr('Рука рядом с прозрачной оболочкой: масштаб «Тишины»','A hand beside the transparent membrane establishes the scale of Silence'),tr('Масштаб: жест рядом с объектом без прикосновения.','Scale: a gesture beside the object without contact.'))+'</div></section>'
    out+=section('author-place',tr('Место автора','The author’s place'),p(tr('Другой образ «Последнего каталога» — девушка на каменном кубе перед зеркалом. Человеческая фигура, отражение и материальность постамента переводят разговор от объекта к присутствию человека.','Another image from The Last Catalog places a woman on a stone cube before a mirror. The figure, reflection, and material presence of the pedestal shift attention from the object to human presence.'))+p(tr('На обложке студии этот образ соседствует с «Тишиной». Это художественная работа, а не утверждение о личности изображённого человека или реальный портрет автора.','On the studio cover, this image sits alongside Silence. It is an artwork, rather than a claim about the identity of the person shown or a real portrait of the author.')),figure('girl-on-cube.webp',tr('Девушка на кубе и её отражение в зеркале','A woman on a cube and her reflection in a mirror'),tr('Оригинальный художественный образ, предоставленный автором проекта.','Original artwork supplied by the project author.'),'image-contain'))
    return out+result(tr('Единый визуальный язык','A consistent visual sequence'),tr('Главный образ, материал, каталожный ракурс и масштаб выполняют разные задачи, сохраняя общий свет и характер.','The main image, material detail, catalog view, and sense of scale serve different roles while retaining consistent light and character.'))+related('silence.html')+contact()

def linked():
    # This independently authored exercise remains reachable at its existing URL, outside the selected work.
    out=intro(tr('Архив · Самостоятельный учебный проект','Archive · Independent portfolio exercise'),'Linked Helper',tr('Продуктовый лендинг по тестовому заданию: исследование, позиционирование, структура и адаптивная реализация. Не клиентский запуск.','A product landing-page concept based on a test assignment: research, positioning, structure, and responsive implementation. Not a client launch.'),'case-hero')
    for title,body in [(tr('Исследование и сообщение','Research and message'),tr('Работа началась с семантического ядра, анализа конкурентов и публичных отзывов. Центральное сообщение объединяет персонализацию и контроль над отправкой сообщений.','The work began with keyword research, competitor analysis, and public reviews. The core message combines personalization with control over messages.')),(tr('Архитектура страницы','Page architecture'),tr('Разработаны карта ценности, система сообщений и последовательность из 16 блоков. Тексты объясняют работу продукта и не используют неподтверждённые метрики конверсии.','Deliverables included value mapping, a message house, and a 16-block page sequence. The copy explains product mechanics without unsupported conversion metrics.')),(tr('Визуальный принцип','Visual principle'),tr('Концепция первого экрана показывает путь от контекста потенциального клиента к черновику и проверке сообщения. Это схема интерфейса, а не скриншот готового продукта.','The hero concept shows the path from prospect context to a draft and review. It is a schematic interface, rather than a screenshot of a finished product.')),(tr('Результат','Outcome'),tr('Подготовлена лёгкая HTML/CSS/JavaScript-реализация с мобильной навигацией и доступной структурой. Проект сохранён как дополнительная работа, вне основных мебельных и каталожных кейсов студии.','A lightweight HTML/CSS/JavaScript implementation was prepared with mobile navigation and accessible structure. It remains an additional project outside the studio’s selected furniture and catalog work.'))]:
        out+=f'<section class="case-result wrap"><h2>{title}</h2><p>{body}</p></section>'
    return out+related('linked-helper.html')

def related(current):
    return '<nav class="related-projects wrap" aria-label="'+tr('Другие проекты','Other projects')+'"><h2>'+tr('Другие проекты','Other projects')+'</h2>'+''.join(link(it[0],tr(it[1],it[2]),'text-link') for it in PROJECTS if it[0]!=current)+'</nav>'

def render(filename,title,description,content,canonical=None):
    current='projects.html' if filename in ['projects.html','otutto.html','forma-home.html','materials.html','silence.html','linked-helper.html'] else filename
    is_home=filename=='index.html'
    nav=''.join(f'<a href="{target}"'+((' aria-current="location"' if page=='projects.html' else ' aria-current="page"') if current==page else '')+(f' data-nav-section="{section_id}"' if is_home and section_id else '')+f'>{label}</a>' for target,label,page,section_id in [('index.html#projects',tr('Проекты','Projects'),'projects.html','projects'),('index.html#services',tr('Услуги','Services'),None,'services'),('price.html',tr('Цены','Price'),'price.html',None),('index.html#contact',tr('Контакты','Contact'),None,'contact')])
    url=BASE+('en/' if LANG=='en' else '')+(canonical or filename)
    alt=('../' if LANG=='en' else 'en/')+filename
    ru=BASE+filename;en=BASE+'en/'+filename
    language_links=f'<a href="{filename}" lang="{LANG}" aria-current="true">{LANG.upper()}</a><a href="{alt}" lang="{tr("en","ru")}" data-language-switch>{tr("EN","RU")}</a>'
    text=f'''<!doctype html>
<html lang="{LANG}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover"><meta name="description" content="{e(description)}"><meta name="theme-color" content="{'#e8e8e3' if is_home else '#071b2b'}"><title>{e(title)} — {tr('Дизайн-студия','Design Studio')}</title>
<link rel="canonical" href="{url}"><link rel="alternate" hreflang="ru" href="{ru}"><link rel="alternate" hreflang="en" href="{en}"><link rel="alternate" hreflang="x-default" href="{ru}">
<meta property="og:type" content="website"><meta property="og:locale" content="{tr('ru_RU','en_US')}"><meta property="og:title" content="{e(title)} — {tr('Дизайн-студия','Design Studio')}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{BASE}assets/studio/otutto-final.webp">
<link rel="icon" type="image/svg+xml" href="{PREFIX}favicon.svg"><link rel="stylesheet" href="{PREFIX}studio.css">{f'<link rel="stylesheet" href="{PREFIX}cover.css">' if is_home else ''}<script defer src="{PREFIX}studio.js"></script></head><body{' class="art-home"' if is_home else ''}>
<a class="skip-link" href="#main">{tr('К содержимому','Skip to content')}</a>
<header class="site-header wrap"><a class="brand" href="index.html" aria-label="{tr('Дизайн-студия — главная','Design Studio — home')}"><span>{tr('Дизайн-студия','Design Studio')}</span><small>{tr('Предмет. Материал. Цифра.','Object. Material. Digital.')}</small></a><nav class="desktop-nav" aria-label="{tr('Основная навигация','Main navigation')}">{nav}</nav><div class="languages" aria-label="{tr('Язык сайта','Site language')}">{language_links}</div><button class="menu-toggle" type="button" data-menu-open aria-controls="site-menu" aria-expanded="false" hidden>{tr('Меню','Menu')}</button><details class="mobile-menu"><summary>{tr('Меню','Menu')}</summary><nav aria-label="{tr('Мобильная навигация','Mobile navigation')}">{nav}<div class="fallback-languages">{language_links}</div></nav></details></header>
<dialog id="site-menu" class="menu-dialog" aria-labelledby="menu-title"><div class="menu-dialog-header"><span id="menu-title">{tr('Навигация','Navigation')}</span><button type="button" data-menu-close>{tr('Закрыть','Close')}<span aria-hidden="true">×</span></button></div><nav aria-label="{tr('Мобильная навигация','Mobile navigation')}">{nav}</nav><div class="menu-languages" aria-label="{tr('Язык сайта','Site language')}">{language_links}</div><div class="menu-contact">{link(contact_url(),tr('Написать в WhatsApp','Message on WhatsApp'),'text-link',True)}{link(email_url(),'sherxanova@gmail.com')}</div></dialog>
<main id="main">{content}</main><footer class="site-footer wrap"><span>{tr('Дизайн-студия','Design Studio')} © 2026</span><span>{tr('Мебель, материалы и цифровые каталоги','Furniture, materials & digital catalogs')}</span>{link('price.html',tr('Услуги и цены','Services & pricing'))}</footer></body></html>'''
    dest=ROOT/('en' if LANG=='en' else '')/filename;dest.write_text(text)

if __name__=='__main__':
    for LANG in ['ru','en']:
        PREFIX='../' if LANG=='en' else ''
        render('index.html',tr('Предмет, материал, цифровой продукт','Objects, materials & digital products'),tr('Дизайн-студия: мебель и текстиль, подбор материалов, визуальная подача, каталоги и сайты-каталоги. Реальные проекты и открытые цены.','Design Studio: furniture, textiles, material selection, visual presentation, catalogs, and catalog websites. Real projects and open pricing.'),home())
        render('projects.html',tr('Проекты','Projects'),tr('Мебель, материалы, визуальные серии и цифровые каталоги. Избранные проекты дизайн-студии.','Furniture, materials, visual series, and digital catalogs. Selected Design Studio projects.'),intro(tr('Работы студии','Studio work'),tr('Предметное.<br><em>И цифровое.</em>','Physical.<br><em>And digital.</em>'),tr('Проекты о том, как создать предмет, показать его характер и сделать ассортимент понятным для выбора.','Projects about creating an object, presenting its character, and making an assortment easy to choose from.'))+'<section class="wrap projects-section">'+projects_grid()+'</section>'+contact())
        render('price.html',tr('Цены','Price'),tr('Открытые стартовые цены на каталоги, сайты мебельных брендов, визуальную подачу и подбор материалов. Базовый объём и реальные примеры.','Open starting prices for catalogs, furniture websites, visual presentation, and material selection. Basic scopes and real examples.'),price())
        for filename,title,fn,desc in [('otutto.html',tr('ОТУТТО','OTUTTO'),otutto,tr('Мебельный проект: визуализация, коммерческие материалы и демонстрационный сайт.','A furniture project: visualization, commercial materials, and a demonstration website.')),('forma-home.html','TETOpt',tetopt,tr('От товарной базы к рабочему каталогу с поиском, фильтрами, карточками и подготовкой заказа.','From product data to a working catalog with search, filters, product details, and inquiry preparation.')),('materials.html',tr('Форма и материал','Form & material'),materials,tr('Работа с мебелью, реальными материалами, фактурой и цветом на примере ОТУТТО.','Working with furniture, real materials, texture, and color through an OTUTTO study.')),('silence.html',tr('Тишина','Silence'),silence,tr('Четыре оригинальных изображения авторской серии «Тишина» из «Последнего каталога».','Four original images of the independent Silence series from The Last Catalog.')),('linked-helper.html','Linked Helper',linked,tr('Архив самостоятельного проекта по продуктовой странице.','Archive of an independent product-page exercise.'))]:render(filename,title,desc,fn())
        aliases={'otutto-visual.html':'materials.html','otutto-commercial.html':'otutto.html#commercial','otutto-storytelling.html':'otutto.html#production','otutto-production.html':'otutto.html#approach','otutto-gpt.html':'otutto.html#approach','tetopt.html':'forma-home.html'}
        for filename,target in aliases.items():
            dest=ROOT/('en' if LANG=='en' else '')/filename
            dest.write_text(f'<!doctype html><html lang="{LANG}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="0;url={target}"><link rel="canonical" href="{BASE}{"en/" if LANG=="en" else ""}{target}"><title>{tr("Проект переехал","Project moved")}</title></head><body><p>{link(target,tr("Перейти к обновлённому проекту","View the updated project"))}</p></body></html>')
